"""Final document assembly. The Sources section is generated by code from resolved citations only.
Compact by design: one line per source document (ids + line ranges) and one line per cited calculation;
verbatim quotes live in evidence.json so the pasted brief stays about a page."""
from __future__ import annotations

import re

from .pipeline import Result
from .validate import CITE


def render(res: Result, ticker: str, today: str) -> str:
    docs = {d.doc_id: d for d in res.docs}
    ev = {e.evidence_id: e for e in res.evidence}
    cd = {c.calc_id: c for c in res.calcs}
    cited = list(dict.fromkeys(CITE.findall(res.brief)))
    per_doc: dict[str, dict[str, list[str]]] = {}
    calc_lines: list[str] = []
    for c in cited:
        if c in ev:
            e = ev[c]
            span = f"L{e.line_start}" if e.line_start == e.line_end else f"L{e.line_start}-{e.line_end}"
            per_doc.setdefault(e.doc_id, {}).setdefault(span, []).append(c)
        elif c in cd:
            calc_lines.append(f"[{c}] {cd[c].text}")
        else:
            m = re.match(r"(D\d+):(L[\d-]+L?\d*)", c)
            if m and m.group(1) in docs:
                per_doc.setdefault(m.group(1), {}).setdefault(m.group(2), []).append(c)
    out = [f"# {ticker} research brief (as of {today})", "", res.brief.strip(), "", "## Sources"]
    for did in sorted(per_doc, key=lambda x: int(x[1:])):
        d = docs[did]
        spans = sorted(per_doc[did].items(), key=lambda kv: int(re.search(r"\d+", kv[0]).group()))
        out.append(f"- **{d.source}**, {d.published} ({d.doc_type}): " + "; ".join(f"{', '.join(sorted(ids))} ({sp})" for sp, ids in spans))
    if calc_lines:
        out.append("- **Python calculations** (inputs in `evidence.json`): " + "; ".join(sorted(calc_lines, key=lambda x: int(re.search(r"\d+", x).group()))))
    out.append("- Exact quotes behind every `[E##]` are in `evidence.json`.")
    ex = [d for d in res.docs if not d.relevant]
    fl = [d for d in res.docs if d.injection_flags]
    out += ["", "_Audit: " + f"mode={res.mode}; {len(res.docs)} documents read; "
            + (f"excluded as a different company: {', '.join(d.filename for d in ex)}; " if ex else "")
            + (f"embedded instructions neutralised in: {', '.join(d.filename for d in fl)}; " if fl else "")
            + f"validation={'PASS' if res.validation and res.validation.ok else 'FAIL'}. Not investment advice._"]
    return "\n".join(out) + "\n"
